/**
 * Wire protocol version, reported by get_bridge_capabilities. Version 1 is every bridge built
 * before the handshake existed; those answer it with Unknown method. Version 2 reassembles
 * messages across reads and frames, answers close and ping frames, validates the upgrade request
 * and serves the handshake. Bump it when a change would make an older client misread the wire.
 */

export const PROTOCOL_VERSION = 2;

/**
 * Native handler ABI version for plugins that register their own handlers. Bump it when the
 * handler signature or registration contract changes in a breaking way. 2: external handlers can
 * register a parameter contract (MCPHandlerSpec.h).
 */

export const HANDLER_API_VERSION = 2;

/**
 * Capability names get_bridge_capabilities advertises. A client asks about the one thing it needs
 * instead of comparing version numbers. Every name is always compiled in and always advertised.
 */

export const BRIDGE_FEATURES = ["frame-reassembly","control-frames","capability-handshake","exclusive-port-claim","owned-port-record","instance-records","requested-port-file","param-echo","handler-specs","call-timeout","session-token","deferred-results","cancel-request","progress-frames"] as const;
export type BridgeFeature = (typeof BRIDGE_FEATURES)[number];

